function renderAll(
  g: Gsel, yStart: number, _seqLen: number, _vocabSize: number, _dModel: number
): { steps: TokStep[]; y: number } {
  const steps: TokStep[] = [];
  let y = yStart;

  // Step 1: Input text
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Text',
      'raw string → character sequence',
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const { width: gridW } = drawCharGrid(gs, CX, rowY, SAMPLE_TEXT);
    lbl(gs, CX - gridW / 2 - 14, rowY, 'text', { size: 12, weight: '700', color: COLORS.text.stroke, anchor: 'end' });
    shapeEq(gs, CX, rowY + CELL / 2 + 28,
      `"${SAMPLE_TEXT}" — ${SAMPLE_TEXT.length} chars (including space)`, COLORS.text.stroke);
    sampleNote(gs, CX, rowY + CELL / 2 + 28 + 34,
      'same input is tokenized by all three algorithms', COLORS.text.stroke);
    y = rowY + CELL / 2 + 28 + 34 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input Text',
      'raw string',
      'Tokenizer input is a raw Unicode string. The first step is to break it into initial units (bytes or characters).',
      'step-input', COLORS.text.stroke, COLORS.text.fill,
      [`text = "${SAMPLE_TEXT}"`]));
  }

  // Step 2: Three algorithms side by side
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-algorithms', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Tokenization Algorithms',
      'BPE · WordPiece · SentencePiece',
      COLORS.vocab.fill, COLORS.vocab.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xLeft = CX - 390;
    const xMid = CX;
    const xRight = CX + 390;

    // BPE card
    const bpeCardW = 340;
    const bpeCardH = 280;
    gs.append('rect').attr('x', xLeft - bpeCardW / 2).attr('y', rowY - bpeCardH / 2).attr('width', bpeCardW).attr('height', bpeCardH)
      .attr('rx', 8).attr('fill', '#fff').attr('stroke', COLORS.bpe.stroke).attr('stroke-width', 1.5);
    lbl(gs, xLeft, rowY - bpeCardH / 2 + 24, 'BPE', { size: 14, weight: '700', color: COLORS.bpe.stroke });
    lbl(gs, xLeft, rowY - bpeCardH / 2 + 44, 'Byte-Pair Encoding', { size: 10, color: COLORS.muted });
    drawFormulaStack(gs, xLeft, rowY - 10, [
      { text: 'init: characters/bytes', color: COLORS.bpe.stroke },
      { text: 'count all adjacent pairs', color: COLORS.bpe.stroke },
      { text: 'merge most frequent pair', color: COLORS.bpe.stroke },
      { text: 'repeat until vocab full', color: COLORS.bpe.stroke },
    ], 260, 24, 8);
    drawTokenSequence(gs, xLeft, rowY + bpeCardH / 2 - 34, BPE_TOKENS, BPE_IDS, COLORS.bpe.stroke, true);

    // WordPiece card
    const wpCardH = 280;
    gs.append('rect').attr('x', xMid - bpeCardW / 2).attr('y', rowY - wpCardH / 2).attr('width', bpeCardW).attr('height', wpCardH)
      .attr('rx', 8).attr('fill', '#fff').attr('stroke', COLORS.wordpiece.stroke).attr('stroke-width', 1.5);
    lbl(gs, xMid, rowY - wpCardH / 2 + 24, 'WordPiece', { size: 14, weight: '700', color: COLORS.wordpiece.stroke });
    lbl(gs, xMid, rowY - wpCardH / 2 + 44, 'Greedy vocabulary match', { size: 10, color: COLORS.muted });
    drawFormulaStack(gs, xMid, rowY - 10, [
      { text: 'prefix ## for subwords', color: COLORS.wordpiece.stroke },
      { text: 'start at leftmost char', color: COLORS.wordpiece.stroke },
      { text: 'pick longest vocab match', color: COLORS.wordpiece.stroke },
      { text: 'continue to next span', color: COLORS.wordpiece.stroke },
    ], 260, 24, 8);
    drawTokenSequence(gs, xMid, rowY + wpCardH / 2 - 34, WP_TOKENS, WP_IDS, COLORS.wordpiece.stroke, true);

    // SentencePiece card
    const spCardH = 280;
    gs.append('rect').attr('x', xRight - bpeCardW / 2).attr('y', rowY - spCardH / 2).attr('width', bpeCardW).attr('height', spCardH)
      .attr('rx', 8).attr('fill', '#fff').attr('stroke', COLORS.sentencepiece.stroke).attr('stroke-width', 1.5);
    lbl(gs, xRight, rowY - spCardH / 2 + 24, 'SentencePiece', { size: 14, weight: '700', color: COLORS.sentencepiece.stroke });
    lbl(gs, xRight, rowY - spCardH / 2 + 44, 'Unigram LM + Viterbi', { size: 10, color: COLORS.muted });
    drawFormulaStack(gs, xRight, rowY - 10, [
      { text: 'treat space as ▁ token', color: COLORS.sentencepiece.stroke },
      { text: 'build segmentation lattice', color: COLORS.sentencepiece.stroke },
      { text: 'score paths with unigram LM', color: COLORS.sentencepiece.stroke },
      { text: 'Viterbi selects best path', color: COLORS.sentencepiece.stroke },
    ], 260, 24, 8);
    drawTokenSequence(gs, xRight, rowY + spCardH / 2 - 34, SP_TOKENS, SP_IDS, COLORS.sentencepiece.stroke, true);

    shapeEq(gs, CX, rowY + bpeCardH / 2 + 28,
      'same string → different subword segmentation', COLORS.vocab.stroke);
    sampleNote(gs, CX, rowY + bpeCardH / 2 + 28 + 32,
      'BPE merges frequent pairs; WordPiece greedily matches; SentencePiece optimizes globally', COLORS.vocab.stroke);
    y = rowY + bpeCardH / 2 + 28 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Algorithms', 'Tokenization Algorithms',
      'BPE | WordPiece | SentencePiece',
      'Three popular subword tokenizers. BPE merges frequent pairs, WordPiece greedily matches the longest vocabulary entry, and SentencePiece uses a unigram language model to find the most probable segmentation.',
      'step-algorithms', COLORS.vocab.stroke, COLORS.vocab.fill));
  }

  // Step 3: Output IDs side by side
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Token IDs',
      'subword tokens → integer IDs → embedding lookup',
      COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xLeft = CX - 360;
    const xMid = CX;
    const xRight = CX + 360;

    lbl(gs, xLeft, rowY - 40, 'BPE ids', { size: 11, weight: '600', color: COLORS.bpe.stroke });
    drawTokenSequence(gs, xLeft, rowY, BPE_TOKENS, BPE_IDS, COLORS.bpe.stroke);

    lbl(gs, xMid, rowY - 40, 'WordPiece ids', { size: 11, weight: '600', color: COLORS.wordpiece.stroke });
    drawTokenSequence(gs, xMid, rowY, WP_TOKENS, WP_IDS, COLORS.wordpiece.stroke);

    lbl(gs, xRight, rowY - 40, 'SentencePiece ids', { size: 11, weight: '600', color: COLORS.sentencepiece.stroke });
    drawTokenSequence(gs, xRight, rowY, SP_TOKENS, SP_IDS, COLORS.sentencepiece.stroke);

    shapeEq(gs, CX, rowY + TOKEN_H / 2 + 36,
      'ids → nn.Embedding(vocab_size, d_model) → token embeddings', COLORS.output.stroke);
    sampleNote(gs, CX, rowY + TOKEN_H / 2 + 36 + 32,
      'different tokenizers produce different ID sequences for the same text', COLORS.output.stroke);
    y = rowY + TOKEN_H / 2 + 36 + 32 + 26 + SHAPE_GAP;
    steps.push(makeStep(stepId, 'Output', 'Token IDs',
      'tokens → ids → embeddings',
      'Token IDs are indices into an embedding table. The same text tokenized by different algorithms yields different ID sequences, but all map to the same d_model embedding space.',
      'step-output', COLORS.output.stroke, COLORS.output.fill));
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// BPE variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderBPE(
  g: Gsel, yStart: number, _seqLen: number, vocabSize: number, _dModel: number
): { steps: TokStep[]; y: number } {
  const steps: TokStep[] = [];
  let y = yStart;

  // Step 1: Input characters
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Characters',
      'text → UTF-8 bytes / characters',
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const chars = SAMPLE_TEXT.split('');
    const { width: gridW } = drawCharGrid(gs, CX, rowY, SAMPLE_TEXT);
    lbl(gs, CX - gridW / 2 - 14, rowY, 'chars', { size: 12, weight: '700', color: COLORS.text.stroke, anchor: 'end' });
    shapeEq(gs, CX, rowY + CELL / 2 + 28,
      `"${SAMPLE_TEXT}" → [${chars.map(c => c === ' ' ? '␣' : c).join(', ')}]`, COLORS.text.stroke);
    sampleNote(gs, CX, rowY + CELL / 2 + 28 + 34,
      'BPE starts from the smallest units (bytes or characters)', COLORS.text.stroke);
    y = rowY + CELL / 2 + 28 + 34 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input Characters',
      'text → characters',
      'BPE begins by splitting text into individual characters or UTF-8 bytes. Spaces are often represented as a special ▁ marker.',
      'step-input', COLORS.text.stroke, COLORS.text.fill,
      [`tokens = list("${SAMPLE_TEXT}")  # [${chars.map(c => `'${c === ' ' ? ' ' : c}'`).join(', ')}]`]));
  }

  // Step 2: Merge table
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-merges', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'BPE Merge Rules',
      'learned from training corpus: rank = merge priority',
      COLORS.merge.fill, COLORS.merge.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xTable = CX - 240;
    const xFormula = CX + 160;
    drawMergeTable(gs, xTable, rowY, BPE_MERGES, COLORS.merge.stroke);
    drawFormulaStack(gs, xFormula, rowY, [
      { text: 'count pair frequencies', color: COLORS.merge.stroke },
      { text: 'merge highest freq pair', color: COLORS.merge.stroke },
      { text: 'add merged token to vocab', color: COLORS.merge.stroke },
      { text: 'repeat to vocab_size', color: COLORS.merge.stroke },
    ], 280, 26, 10);
    shapeEq(gs, CX, rowY + 120,
      `vocab_size = ${vocabSize} | merges learned offline from corpus`, COLORS.merge.stroke);
    sampleNote(gs, CX, rowY + 120 + 32,
      'merge order is fixed after training; inference only applies existing rules', COLORS.merge.stroke);
    y = rowY + 120 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Merges', 'BPE Merge Rules',
      'merge most frequent adjacent pair',
      'During training, BPE counts all adjacent symbol pairs and repeatedly merges the most frequent one. Each merge creates a new vocabulary entry.',
      'step-merges', COLORS.merge.stroke, COLORS.merge.fill,
      [`while len(vocab) < vocab_size:`, `    pair = most_frequent(pairs)`, `    vocab.append(merge(pair))`]));
  }

  // Step 3: Apply merges
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-apply', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Apply Merges',
      'iterate through merge table in rank order; replace every matching pair',
      COLORS.bpe.fill, COLORS.bpe.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const hiFill = '#ffedd5';
    const stages: { tokens: string[]; highlight: [number, number] | null; merge: string; label: string }[] = [
      { tokens: ['d', 'e', 'e', 'p', 'Ġ', 'l', 'e', 'a', 'r', 'n', 'i', 'n', 'g'], highlight: null, merge: '', label: 'initial characters' },
      { tokens: ['d', 'e', 'e', 'p', 'Ġ', 'l', 'e', 'a', 'r', 'n', 'i', 'n', 'g'], highlight: [1, 3], merge: 'e + e → ee', label: 'rank 1' },
      { tokens: ['d', 'ee', 'p', 'Ġ', 'l', 'e', 'a', 'r', 'n', 'i', 'n', 'g'], highlight: [9, 11], merge: 'i + n → in', label: 'rank 2' },
      { tokens: ['d', 'ee', 'p', 'Ġ', 'l', 'e', 'a', 'r', 'n', 'in', 'g'], highlight: [8, 10], merge: 'n + in → nin', label: 'rank 3' },
      { tokens: ['d', 'ee', 'p', 'Ġ', 'l', 'e', 'a', 'r', 'nin', 'g'], highlight: [0, 2], merge: 'd + ee → dee', label: 'rank 4' },
      { tokens: ['dee', 'p', 'Ġ', 'l', 'e', 'a', 'r', 'nin', 'g'], highlight: [0, 2], merge: 'dee + p → deep', label: 'rank 5' },
      { tokens: ['deep', 'Ġ', 'l', 'e', 'a', 'r', 'nin', 'g'], highlight: [2, 4], merge: 'a + r → ar', label: 'rank 6' },
      { tokens: ['deep', 'Ġ', 'l', 'e', 'ar', 'nin', 'g'], highlight: [3, 5], merge: 'e + ar → ear', label: 'rank 7' },
      { tokens: ['deep', 'Ġ', 'l', 'ear', 'nin', 'g'], highlight: [2, 4], merge: 'l + ear → lear', label: 'rank 8' },
      { tokens: ['deep', 'Ġ', 'lear', 'nin', 'g'], highlight: [3, 5], merge: 'nin + g → ning', label: 'rank 9' },
      { tokens: ['deep', 'Ġlearning'], highlight: null, merge: '', label: 'Ġ + learning → Ġlearning (rank 10)' },
    ];

    const stageGap = 92;
    let stageY = rowY;
    for (let i = 0; i < stages.length; i++) {
      const stage = stages[i];
      const bottomY = drawMergeStage(gs, CX, stageY, stage.tokens, stage.highlight, stage.merge, stage.label, COLORS.bpe.stroke, hiFill);
      if (i < stages.length - 1) {
        arrowV(gs, CX, bottomY + 4, stageY + stageGap - SMALL_TOKEN_H / 2 - 18, COLORS.bpe.stroke, 10);
      }
      stageY += stageGap;
    }

    shapeEq(gs, CX, stageY + 18,
      'BPE: deterministic, greedy application of merge ranks', COLORS.bpe.stroke);
    sampleNote(gs, CX, stageY + 18 + 38,
      'each merge reduces token count; process stops when no merge rule matches', COLORS.bpe.stroke);
    y = stageY + 18 + 38 + 28 + STEP_GAP;
    steps.push(makeStep(stepId, 'Apply', 'Apply Merges',
      'apply merge rules in order',
      'At inference time, BPE scans the merge table from rank 1 to N. For each rule, it replaces every occurrence of the pair in the current token sequence.',
      'step-apply', COLORS.bpe.stroke, COLORS.bpe.fill,
      [`for rank, (a, b) in merges:`, `    tokens = tokens.replace((a, b), a+b)`]));
  }

  // Step 4: Vocab + IDs
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-vocab', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Vocabulary Lookup',
      'final subwords → integer IDs',
      COLORS.vocab.fill, COLORS.vocab.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xVocab = CX - 260;
    const xTokens = CX + 160;
    drawVocabTable(gs, xVocab, rowY, BPE_VOCAB.slice(-6), COLORS.vocab.stroke, 8);
    lbl(gs, xVocab, rowY - 110, 'selected vocab entries', { size: 11, weight: '600', color: COLORS.vocab.stroke });
    drawTokenSequence(gs, xTokens, rowY, BPE_TOKENS, BPE_IDS, COLORS.bpe.stroke);
    arrowH(gs, xVocab + 120, xTokens - 120, rowY, COLORS.bpe.stroke, 20);
    shapeEq(gs, CX, rowY + TOKEN_H / 2 + 36,
      `tokens [${BPE_TOKENS.length}] → ids [${BPE_IDS.join(', ')}]`, COLORS.vocab.stroke);
    sampleNote(gs, CX, rowY + TOKEN_H / 2 + 36 + 32,
      'OOV words are split into known subwords; rare characters fall back to bytes', COLORS.vocab.stroke);
    y = rowY + TOKEN_H / 2 + 36 + 32 + 26 + SHAPE_GAP;
    steps.push(makeStep(stepId, 'Lookup', 'Vocabulary Lookup',
      'subword → id',
      'The final subword tokens are looked up in the vocabulary table. IDs are then used to index the embedding matrix.',
      'step-vocab', COLORS.vocab.stroke, COLORS.vocab.fill,
      [`ids = [vocab[t] for t in tokens]`]));
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// WordPiece variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderWordPiece(
  g: Gsel, yStart: number, _seqLen: number, vocabSize: number, _dModel: number
): { steps: TokStep[]; y: number } {
  const steps: TokStep[] = [];
  let y = yStart;

  // Step 1: Input with prefix marker
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Prefix-Marked Input',
      'WordPiece marks subword continuations with ##',
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const words = ['deep', 'learning'];
    const wordXs = [CX - 200, CX + 120];
    for (let i = 0; i < words.length; i++) {
      const wx = wordXs[i];
      drawCharGrid(gs, wx, rowY, words[i]);
      lbl(gs, wx, rowY - CELL / 2 - 18, 'word start', { size: 10, color: COLORS.muted });
    }
    // show ## label next to subword pieces of "learning"
    const learnW = words[1].length * CELL;
    lbl(gs, wordXs[1] - learnW / 2 - 10, rowY + CELL / 2 + 22, '→ l + ##ear + ##n + ##ing', { size: 10, color: COLORS.wordpiece.stroke, anchor: 'end' });
    // divider
    g.append('line')
      .attr('x1', CX - 10).attr('y1', rowY - CELL / 2 - 8)
      .attr('x2', CX - 10).attr('y2', rowY + CELL / 2 + 8)
      .attr('stroke', '#cbd5e1').attr('stroke-width', 1.5).attr('stroke-dasharray', '4,4');
    lbl(gs, CX - 10, rowY - CELL / 2 - 24, 'word boundary', { size: 9, color: COLORS.muted });
    shapeEq(gs, CX, rowY + CELL / 2 + 56,
      'space separates words; first subword has no prefix', COLORS.text.stroke);
    sampleNote(gs, CX, rowY + CELL / 2 + 56 + 32,
      '## indicates the token continues a previous word piece', COLORS.wordpiece.stroke);
    y = rowY + CELL / 2 + 56 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Prefix-Marked Input',
      'text → words → ## continuation markers',
      'WordPiece tokenizes each word independently. The first piece of a word has no prefix; all continuation pieces are prefixed with ##.',
      'step-input', COLORS.text.stroke, COLORS.text.fill,
      [`tokens = []`, `for word in text.split():`, `    tokens.extend(wordpiece_tokenize(word))`]));
  }

  // Step 2: Vocabulary
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-vocab', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'WordPiece Vocabulary',
      `vocab_size = ${vocabSize}`,
      COLORS.vocab.fill, COLORS.vocab.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xVocab = CX - 260;
    const xDesc = CX + 160;
    drawVocabTable(gs, xVocab, rowY, WP_VOCAB, COLORS.vocab.stroke, 8);
    drawFormulaStack(gs, xDesc, rowY, [
      { text: 'train: maximize likelihood', color: COLORS.wordpiece.stroke },
      { text: 'keep candidates that help P(data)', color: COLORS.wordpiece.stroke },
      { text: 'inference: longest-match greedy', color: COLORS.wordpiece.stroke },
    ], 280, 26, 10);
    shapeEq(gs, CX, rowY + 120,
      'vocab includes full words + subwords (## prefix)', COLORS.vocab.stroke);
    sampleNote(gs, CX, rowY + 120 + 32,
      'WordPiece vocab is optimized to maximize training data likelihood', COLORS.vocab.stroke);
    y = rowY + 120 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Vocab', 'WordPiece Vocabulary',
      'likelihood-maximizing subword inventory',
      'Unlike BPE, WordPiece does not merge by frequency. It adds the subword that maximizes the likelihood of the training corpus.',
      'step-vocab', COLORS.vocab.stroke, COLORS.vocab.fill,
      [`vocab = train_wordpiece(corpus, vocab_size=${vocabSize})`]));
  }

  // Step 3: Greedy match
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-match', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Greedy Longest Match',
      'at each position, pick longest vocabulary entry',
      COLORS.wordpiece.fill, COLORS.wordpiece.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const word = 'learning';
    const positions = [0, 1, 4, 5];
    const matches = ['l', 'ear', 'n', 'ing'];
    const prefixes = ['', '##', '##', '##'];

    drawCharGrid(gs, CX, rowY, word);
    const gridW = word.length * CELL;
    const tokenY = rowY + CELL / 2 + 64;

    for (let i = 0; i < positions.length; i++) {
      const start = positions[i];
      const end = i < positions.length - 1 ? positions[i + 1] : word.length;
      const spanW = (end - start) * CELL;
      const sx = CX - gridW / 2 + start * CELL + spanW / 2;
      g.append('rect')
        .attr('x', sx - spanW / 2 + 2).attr('y', rowY - CELL / 2 + 2)
        .attr('width', spanW - 4).attr('height', CELL - 4)
        .attr('fill', COLORS.wordpiece.stroke).attr('opacity', 0.15).attr('rx', 2)
        .attr('stroke', COLORS.wordpiece.stroke).attr('stroke-width', 1.5);
      const tx = sx;
      g.append('rect').attr('x', tx - SMALL_TOKEN_W / 2).attr('y', tokenY - SMALL_TOKEN_H / 2).attr('width', SMALL_TOKEN_W).attr('height', SMALL_TOKEN_H)
        .attr('rx', 3).attr('fill', '#fff').attr('stroke', COLORS.wordpiece.stroke).attr('stroke-width', 1.5);
      lbl(g, tx, tokenY, prefixes[i] + matches[i], { size: 10, weight: '600', color: COLORS.wordpiece.stroke });
      arrowV(gs, sx, rowY + CELL / 2 - 2, tokenY - SMALL_TOKEN_H / 2, COLORS.wordpiece.stroke, 8);
      lbl(g, sx, rowY + CELL / 2 + 18, `${i + 1}`, { size: 9, color: COLORS.wordpiece.stroke });
    }

    shapeEq(gs, CX, tokenY + SMALL_TOKEN_H / 2 + 34,
      '"learning" → [l, ##ear, ##n, ##ing]', COLORS.wordpiece.stroke);
    sampleNote(gs, CX, tokenY + SMALL_TOKEN_H / 2 + 34 + 32,
      'greedy: at each step, consume the longest matching vocab entry', COLORS.wordpiece.stroke);
    y = tokenY + SMALL_TOKEN_H / 2 + 34 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Match', 'Greedy Longest Match',
      'longest-match tokenization',
      'Starting from the first character, WordPiece consumes the longest substring that exists in the vocabulary. Continuation pieces keep the ## prefix.',
      'step-match', COLORS.wordpiece.stroke, COLORS.wordpiece.fill,
      [`while pos < len(word):`, `    token = longest_match(word[pos:], vocab)`, `    pos += len(token)`]));
  }

  // Step 4: Output IDs
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'WordPiece Output',
      'subwords → integer IDs',
      COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    drawTokenSequence(gs, CX, rowY, WP_TOKENS, WP_IDS, COLORS.wordpiece.stroke);
    shapeEq(gs, CX, rowY + TOKEN_H / 2 + 36,
      `WordPiece("${SAMPLE_TEXT}") → [${WP_IDS.join(', ')}]`, COLORS.wordpiece.stroke);
    sampleNote(gs, CX, rowY + TOKEN_H / 2 + 36 + 32,
      'first token of each word has no ##; continuation tokens do', COLORS.wordpiece.stroke);
    y = rowY + TOKEN_H / 2 + 36 + 32 + 26 + SHAPE_GAP;
    steps.push(makeStep(stepId, 'Output', 'WordPiece Output',
      'subwords → ids',
      'The final WordPiece token sequence is mapped to IDs. The ## markers are only structural hints; the embedding lookup uses the full token string.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`ids = [vocab[t] for t in tokens]  # [${WP_IDS.join(', ')}]`]));
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// SentencePiece variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderSentencePiece(
  g: Gsel, yStart: number, _seqLen: number, vocabSize: number, _dModel: number
): { steps: TokStep[]; y: number } {
  const steps: TokStep[] = [];
  let y = yStart;

  // Step 1: Input with ▁ marker
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input with ▁ Marker',
      'SentencePiece treats space as a regular token',
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const marked = '▁deep▁learning';
    const { width: gridW } = drawCharGrid(gs, CX, rowY, marked);
    lbl(gs, CX - gridW / 2 - 14, rowY, 'text', { size: 12, weight: '700', color: COLORS.text.stroke, anchor: 'end' });
    shapeEq(gs, CX, rowY + CELL / 2 + 28,
      `"${SAMPLE_TEXT}" → "▁deep▁learning"`, COLORS.text.stroke);
    sampleNote(gs, CX, rowY + CELL / 2 + 28 + 34,
      '▁ marks word boundary; tokenizer is language-agnostic', COLORS.sentencepiece.stroke);
    y = rowY + CELL / 2 + 28 + 34 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input with ▁ Marker',
      'text → ▁-marked string',
      'SentencePiece converts spaces into a special ▁ symbol and tokenizes the entire string as a sequence of Unicode characters. This makes it language-agnostic.',
      'step-input', COLORS.text.stroke, COLORS.text.fill,
      [`text = text.replace(' ', '▁')  # "▁deep▁learning"`]));
  }

  // Step 2: Unigram vocabulary
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-vocab', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Unigram Vocabulary',
      `vocab_size = ${vocabSize}; each entry has a log-probability score`,
      COLORS.vocab.fill, COLORS.vocab.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xVocab = CX - 260;
    const xDesc = CX + 160;
    drawVocabTable(gs, xVocab, rowY, SP_VOCAB.map(e => ({ token: `${e.token} (${e.score})`, id: e.id })), COLORS.vocab.stroke, 8);
    drawFormulaStack(gs, xDesc, rowY, [
      { text: 'start with large seed vocab', color: COLORS.sentencepiece.stroke },
      { text: 'EM algorithm estimates P(token)', color: COLORS.sentencepiece.stroke },
      { text: 'prune tokens that hurt likelihood', color: COLORS.sentencepiece.stroke },
      { text: 'keep top vocab_size entries', color: COLORS.sentencepiece.stroke },
    ], 280, 26, 10);
    shapeEq(gs, CX, rowY + 120,
      'Unigram LM: score(path) = Σ log P(token)', COLORS.vocab.stroke);
    sampleNote(gs, CX, rowY + 120 + 32,
      'lower (more negative) score = less likely token', COLORS.sentencepiece.stroke);
    y = rowY + 120 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Vocab', 'Unigram Vocabulary',
      'each token has a probability score',
      'SentencePiece (Unigram) trains a unigram language model over subword candidates. Each vocabulary entry has a log-probability used to score segmentations.',
      'step-vocab', COLORS.vocab.stroke, COLORS.vocab.fill,
      [`vocab, scores = train_unigram(corpus, vocab_size=${vocabSize})`]));
  }

  // Step 3: Lattice + Viterbi
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-viterbi', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Lattice + Viterbi',
      'find highest-probability segmentation path',
      COLORS.sentencepiece.fill, COLORS.sentencepiece.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const nodes = [0, 1, 5, 6, 14];
    const nodeLabels = ['▁', 'deep', '▁', 'learning'];
    const nodeScores = [-0.8, -2.1, -0.8, -2.4];
    const nodeColors = ['#94a3b8', COLORS.sentencepiece.stroke, '#94a3b8', COLORS.sentencepiece.stroke];

    const nodeGap = 108;
    const startX = CX - ((nodes.length - 1) * nodeGap) / 2;
    const nodeY = rowY;

    // baseline
    g.append('line')
      .attr('x1', startX - 20).attr('y1', nodeY)
      .attr('x2', startX + (nodes.length - 1) * nodeGap + 20).attr('y2', nodeY)
      .attr('stroke', '#cbd5e1').attr('stroke-width', 2);
    lbl(g, startX - 28, nodeY, 'start', { size: 9, color: '#94a3b8', anchor: 'end' });

    for (let i = 0; i < nodes.length - 1; i++) {
      const nx = startX + i * nodeGap;
      g.append('circle').attr('cx', nx).attr('cy', nodeY).attr('r', 6).attr('fill', '#fff').attr('stroke', nodeColors[i]).attr('stroke-width', 2);
      const nextX = startX + (i + 1) * nodeGap;
      g.append('line')
        .attr('x1', nx + 6).attr('y1', nodeY)
        .attr('x2', nextX - 6).attr('y2', nodeY)
        .attr('stroke', COLORS.sentencepiece.stroke).attr('stroke-width', 2.5);
      const midX = (nx + nextX) / 2;
      const labelW = nodeLabels[i].length * 8 + 18;
      g.append('rect').attr('x', midX - labelW / 2).attr('y', nodeY - 26).attr('width', labelW).attr('height', 22)
        .attr('rx', 3).attr('fill', '#fff').attr('stroke', nodeColors[i]).attr('stroke-width', 1);
      lbl(g, midX, nodeY - 16, nodeLabels[i], { size: 10, weight: '600', color: nodeColors[i] });
      lbl(g, midX, nodeY + 18, String(nodeScores[i]), { size: 9, color: COLORS.muted, font: 'monospace' });
    }
    g.append('circle')
      .attr('cx', startX + (nodes.length - 1) * nodeGap).attr('cy', nodeY).attr('r', 6)
      .attr('fill', '#fff').attr('stroke', COLORS.sentencepiece.stroke).attr('stroke-width', 2);
    lbl(g, startX + (nodes.length - 1) * nodeGap + 14, nodeY, 'end', { size: 9, color: '#94a3b8', anchor: 'start' });

    // alternative path: ▁deep ▁learn ing
    const altY = nodeY + 86;
    g.append('line')
      .attr('x1', startX - 20).attr('y1', altY)
      .attr('x2', startX + (nodes.length - 1) * nodeGap + 20).attr('y2', altY)
      .attr('stroke', '#e2e8f0').attr('stroke-width', 1.5).attr('stroke-dasharray', '4,4');
    const altNodes = [0, 5, 6, 10, 14];
    const altLabels = ['▁deep', '▁', 'learn', 'ing'];
    const altScores = [-2.9, -0.8, -3.2, -3.6];
    for (let i = 0; i < altNodes.length - 1; i++) {
      const nx = startX + (altNodes[i] / 14) * ((nodes.length - 1) * nodeGap);
      const nextX = startX + (altNodes[i + 1] / 14) * ((nodes.length - 1) * nodeGap);
      g.append('line')
        .attr('x1', nx + 6).attr('y1', altY)
        .attr('x2', nextX - 6).attr('y2', altY)
        .attr('stroke', '#cbd5e1').attr('stroke-width', 1.5);
      const midX = (nx + nextX) / 2;
      const labelW = altLabels[i].length * 8 + 14;
      g.append('rect').attr('x', midX - labelW / 2).attr('y', altY - 20).attr('width', labelW).attr('height', 16)
        .attr('rx', 3).attr('fill', '#fff').attr('stroke', '#cbd5e1').attr('stroke-width', 0.5);
      lbl(g, midX, altY - 12, altLabels[i], { size: 9, color: '#94a3b8' });
      lbl(g, midX, altY + 14, String(altScores[i]), { size: 8, color: '#94a3b8', font: 'monospace' });
    }
    lbl(gs, CX, altY + 36, 'alternative path (lower total score)', { size: 9, color: '#94a3b8' });

    shapeEq(gs, CX, altY + 64,
      'Viterbi: best path = argmax Σ log P(token)', COLORS.sentencepiece.stroke);
    sampleNote(gs, CX, altY + 64 + 32,
      'global optimization: chooses the segmentation with highest joint probability', COLORS.sentencepiece.stroke);
    y = altY + 64 + 32 + 26 + STEP_GAP;
    steps.push(makeStep(stepId, 'Viterbi', 'Lattice + Viterbi',
      'argmax over all segmentations',
      'SentencePiece builds a lattice of all possible segmentations and uses Viterbi to find the path with the highest total unigram probability.',
      'step-viterbi', COLORS.sentencepiece.stroke, COLORS.sentencepiece.fill,
      [`lattice = build_lattice(text, vocab)`, `best_path = viterbi(lattice, scores)`]));
  }

  // Step 4: Output IDs
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'SentencePiece Output',
      'best-path tokens → integer IDs',
      COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    drawTokenSequence(gs, CX, rowY, SP_TOKENS, SP_IDS, COLORS.sentencepiece.stroke);
    shapeEq(gs, CX, rowY + TOKEN_H / 2 + 36,
      `SentencePiece("${SAMPLE_TEXT}") → [${SP_IDS.join(', ')}]`, COLORS.sentencepiece.stroke);
    sampleNote(gs, CX, rowY + TOKEN_H / 2 + 36 + 32,
      'decoded text: ids → tokens → replace ▁ with space', COLORS.sentencepiece.stroke);
    y = rowY + TOKEN_H / 2 + 36 + 32 + 26 + SHAPE_GAP;
    steps.push(makeStep(stepId, 'Output', 'SentencePiece Output',
      'tokens → ids',
      'The best segmentation is mapped to IDs. Decoding reverses the process, converting ▁ back to spaces.',
      'step-output', COLORS.output.stroke, COLORS.output.fill,
      [`ids = [vocab[t] for t in best_path]  # [${SP_IDS.join(', ')}]`]));
  }

  return { steps, y };
}

