// Main export
// ═══════════════════════════════════════════════════════════════════════════════

export function renderTokenizerDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const vocabSize = Number(params.vocab_size) || 32000;
  const dModel = Number(params.d_model) || 512;
  const variant = String(params.variant || 'all') as TokVariant;

  const stepsMeta: TokStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Tokenizer', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  const variantLabel = variant === 'bpe'
    ? 'Byte-Pair Encoding (BPE)'
    : variant === 'wordpiece'
      ? 'WordPiece'
      : variant === 'sentencepiece'
        ? 'SentencePiece (Unigram)'
        : 'BPE · WordPiece · SentencePiece Comparison';
  lbl(g, CX, y + 8,
    `${variantLabel} — subword tokenization`,
    { size: 10, color: 'var(--text-muted)' });
  y += 30;

  g.append('rect')
    .attr('x', CX - 300).attr('y', y).attr('width', 600).attr('height', 36)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const items = [`seq_len: ${seqLen}`, `vocab_size: ${vocabSize}`, `d_model: ${dModel}`, `variant: ${variant}`];
  const segW = 600 / items.length;
  items.forEach((item, i) => {
    lbl(g, CX - 300 + segW * (i + 0.5), y + 19, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  y += 50;

  const { steps, y: finalY } = variant === 'bpe'
    ? renderBPE(g, y, seqLen, vocabSize, dModel)
    : variant === 'wordpiece'
      ? renderWordPiece(g, y, seqLen, vocabSize, dModel)
      : variant === 'sentencepiece'
        ? renderSentencePiece(g, y, seqLen, vocabSize, dModel)
        : renderAll(g, y, seqLen, vocabSize, dModel);
  stepsMeta.push(...steps);
  y = finalY;

  // ── Footer ─────────────────────────────────────────────────────────────────
  y += FOOTER_PAD;

  const insightText = variant === 'bpe'
    ? 'BPE (GPT-style) starts from characters or bytes and learns merge rules from a training corpus. It is deterministic and greedy: at inference, it applies the learned merge ranks in order. Frequent subwords become single tokens; rare or unseen words are split into known pieces.'
    : variant === 'wordpiece'
      ? 'WordPiece (BERT-style) tokenizes by greedy longest-match against a vocabulary optimized to maximize training-data likelihood. Continuation subwords are marked with ## so the model can distinguish word-start from word-inside pieces.'
      : variant === 'sentencepiece'
        ? 'SentencePiece (Unigram, T5/Llama-style) treats space as a regular ▁ token, making it language-agnostic. It builds all possible segmentations, scores them with a unigram language model, and uses Viterbi to select the globally best path.'
        : 'Subword tokenizers balance vocabulary size and coverage. BPE merges frequent pairs; WordPiece greedily matches a likelihood-maximizing vocabulary; SentencePiece globally optimizes segmentation with a unigram LM. The same string can yield different token counts and IDs.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = variant === 'bpe'
    ? `Vocab size ${vocabSize}. BPE training is O(corpus_size × merges) but inference is O(text length × merges). Byte-level BPE handles any Unicode input without unknown tokens.`
    : variant === 'wordpiece'
      ? `Vocab size ${vocabSize}. WordPiece inference is O(text length × vocab) with trie acceleration. It requires language-specific pre-tokenization (whitespace split).`
      : variant === 'sentencepiece'
        ? `Vocab size ${vocabSize}. SentencePiece inference is O(text length × vocab) for lattice construction plus O(nodes) for Viterbi. No whitespace pre-tokenization needed.`
        : `Vocab size ${vocabSize}. All three produce O(sequence length) IDs. BPE and SentencePiece are language-agnostic; WordPiece needs whitespace splitting. Embedding table size is ${vocabSize} × ${dModel} = ${(vocabSize * dModel).toLocaleString()} parameters.`;

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'norm-comparison', 'Norm Comparison');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'cross-entropy', 'Cross Entropy');
  y += 80;

  const codeTitle = variant === 'bpe'
    ? 'BPE Tokenization (Python)'
    : variant === 'wordpiece'
      ? 'WordPiece Tokenization (Python)'
      : variant === 'sentencepiece'
        ? 'SentencePiece Tokenization (Python)'
        : 'Tokenizer Comparison (Python)';

  const descLine = variant === 'bpe'
    ? 'BPE: merge frequent pairs'
    : variant === 'wordpiece'
      ? 'WordPiece: greedy longest match'
      : variant === 'sentencepiece'
        ? 'SentencePiece: unigram LM + Viterbi'
        : 'BPE / WordPiece / SentencePiece';

  const codeText = variant === 'bpe'
    ? `from transformers import AutoTokenizer

tokenizer = AutoTokenizer.from_pretrained("gpt2")
ids = tokenizer.encode("${SAMPLE_TEXT}")
# e.g. [${BPE_IDS.join(', ')}]

tokens = tokenizer.convert_ids_to_tokens(ids)
# e.g. [${BPE_TOKENS.map(t => `"${t}"`).join(', ')}]`
    : variant === 'wordpiece'
      ? `from transformers import AutoTokenizer

tokenizer = AutoTokenizer.from_pretrained("bert-base-uncased")
ids = tokenizer.encode("${SAMPLE_TEXT}")
# e.g. [${WP_IDS.join(', ')}]

tokens = tokenizer.convert_ids_to_tokens(ids)
# e.g. [${WP_TOKENS.map(t => `"${t}"`).join(', ')}]`
      : variant === 'sentencepiece'
        ? `import sentencepiece as spm

sp = spm.SentencePieceProcessor(model_file="tokenizer.model")
ids = sp.encode("${SAMPLE_TEXT}")
# e.g. [${SP_IDS.join(', ')}]

tokens = [sp.id_to_piece(i) for i in ids]
# e.g. [${SP_TOKENS.map(t => `"${t}"`).join(', ')}]`
        : `# BPE (GPT-2)
from transformers import AutoTokenizer
tokenizer = AutoTokenizer.from_pretrained("gpt2")
ids = tokenizer.encode("${SAMPLE_TEXT}")

# WordPiece (BERT)
tokenizer = AutoTokenizer.from_pretrained("bert-base-uncased")
ids = tokenizer.encode("${SAMPLE_TEXT}")

# SentencePiece (Llama/T5)
import sentencepiece as spm
sp = spm.SentencePieceProcessor(model_file="tokenizer.model")
ids = sp.encode("${SAMPLE_TEXT}")`;

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    codeTitle,
    [descLine],
    codeText.split('\n'));
  y += 32;

  return { width: W, height: y, steps: stepsMeta };
}
